import { Route, Routes, useParams } from "react-router-dom";
import Homepage from "./component/Homepage";
import TheoryPage from "./component/TheoryPage";
import MathsQuiz from "./quiz/MathsQuiz";
import Level1 from "./component/Level1";
import Level2 from "./component/Level2";
import SelectLevel from "./component/SelectLevel";
import ReactGA from "react-ga4";
import useWebSocket from "react-use-websocket";
import logconfig from "./config/dbconfig";
import { v4 as uuid } from "uuid";
import axios from "axios";
import { useEffect, useState } from "react";
import Procedure from "./component/Procedure";
import Level3 from "./component/Level3";
import Animation from "./component/Animation";
import Language from "./Language";
import { useTranslation } from "react-i18next";
import { useDispatch, useSelector } from "react-redux";
import setLangStore, { changeLang } from "./store/Store";
import RestartPage from "./component/RestartPage";

function App() {
  const { id } = useParams();
  const [ip, setIP] = useState("");
  let dispatch = useDispatch();
  const sid = uuid();
  const { t, i18n } = useTranslation();

  useEffect(() => {
    localStorage.setItem("sessionid", sid);
  }, []);

  useEffect(() => {
    // to call get data function which return ip address
    getData();
  }, [ip]);

  const getData = async () => {
    try {
      //const res = await axios.get('https://api.ipify.org/?format=json')
      // const res = await axios.get("http://10.212.8.133:8083/get_ip");
      //console.log(res.data);
      // setIP(res.data.ip);
      localStorage.setItem("clientip", ip);
    } catch (error) {}
  };

  const { sendJsonMessage, readyState } = useWebSocket(logconfig.logurl, {
    onOpen: () => {
      console.log("WebSocket connection established.");
    },
    onError: () => {
      console.log("WebSocket connection Error");
    },
    share: true,
    filter: () => false,
    retryOnError: true,
    shouldReconnect: () => true,
  });

  useEffect(() => {
    ReactGA.initialize("G-ZLKNSX7SDM", {
      gaOptions: {
        gtag: true,
      },
    });
  }, []);

  useEffect(() => {
    if (id == "en") {
      alert("in app en : ", id);
      i18n.changeLanguage("en");
      dispatch(changeLang("en"));
    }
    if (id == "hn") {
      alert("in app hn : ", id);
      i18n.changeLanguage("hn");
      dispatch(changeLang("hn"));
    }
  }, []);

  return (
    <Routes>
      <Route path="/:id" element={<App />} />
      <Route exact path="/" element={<Homepage />} />
      <Route exact path="/letusverify" element={<Homepage />} />
      <Route
        exact
        path="/launchpage/englishactivity"
        element={<SelectLevel />}
      />
      <Route
        exact
        path="/launchpage/englishactivity/level1"
        element={<Level1 />}
      />
      <Route
        exact
        path="/launchpage/englishactivity/selectlevel/level1/restart"
        element={<RestartPage />}
      />
      <Route
        exact
        path="/launchpage/englishactivity/level1/level2"
        element={<Level2 />}
      />
      <Route
        exact
        path="/launchpage/englishactivity/selectlevel/level1/level2/restart"
        element={<RestartPage />}
      />
      <Route
        exact
        path="/launchpage/englishactivity/level1/level2/level3"
        element={<Level3 />}
      />
      <Route
        exact
        path="/launchpage/englishactivity/selectlevel/level1/level2/level3/restart"
        element={<RestartPage />}
      />
      <Route exact path="/theory" element={<TheoryPage />} />
      <Route exact path="/procedure" element={<Procedure />} />
      <Route exact path="/quiz" element={<MathsQuiz />} />
      <Route exact path="/animation" element={<Animation />}></Route>
    </Routes>
  );
}

export default App;
