import React, { useEffect, useState } from "react";
import detailsOfSelLetter from "../personalAndPossessive.json";
import { useNavigate } from "react-router-dom";
import useWebSocket, { ReadyState } from "react-use-websocket";
import logconfig from "../config/dbconfig";
import { SendLogData } from "../config/wslog.js";
import ReactGA from "react-ga4";
import Swal from "sweetalert2";
import { Button, FormControl, MenuItem, Select, Slider } from "@mui/material";
import { useTranslation } from "react-i18next";

const Level3MidContent = () => {
  const { t } = useTranslation();
  const parse = require("html-react-parser").default;
  const [pageName, setpageName] = useState("Level-3");
  let [randomNumber, setRandomNumber] = useState(0);
  let [randomNumberArray, setRandomNumberArray] = useState([0]);
  let [skipCount, setSkipCount] = useState(0);
  const navigate = useNavigate();
  var [finalIdxActHiddnWordSent, setIdxActHiddnWordSent] = useState([]);
  // Details of Complete List of Hidden Words Found
  var [finalCompleteList, setFinalCompleteList] = useState([]);
  const { sendJsonMessage } = useWebSocket(logconfig.logurl, { share: true });
  let [answerArray, setAnswerArray] = useState([]);
  let [selectedAns, setSelectedAns] = useState([]);
  let [showMessage, setShowMessage] = useState(false);
  let [fbMessage, setFbMessage] = useState("");
  const [level, setLevel] = useState("Level 3");
  let [disabledNext, setDisabledNext] = useState(true);
  let [flag, setFlag] = useState(false);

  function randomNumberInRange(min, max) {
    return Math.floor(Math.random() * (max - min)) + min;
  }

  function getDetailsOfHiddenWords(mapOfDetails) {
    var idxHiddenWord = [];
    var listOfHiddenWords = [];
    var idxActHddnWordSent = [];

    // Start : Load content of From Sentence Map ..........
    mapOfDetails.map((item, idx) => {
      var sentHiddenWords = item.hidden;
      var hiddenLen = sentHiddenWords.length;

      if (hiddenLen === 0 || (hiddenLen === 1 && sentHiddenWords[0] === "")) {
        idxHiddenWord.push(-1);
        listOfHiddenWords.push("");
        idxActHddnWordSent.push(-1);
      } else {
        var hiddenIdx = randomNumberInRange(0, hiddenLen);
        var sentsplit = ([] = item.sentence.split(" "));
        idxHiddenWord.push(hiddenIdx);

        if (sentsplit.includes(sentHiddenWords[hiddenIdx])) {
          var hiddenWord =
            sentsplit[sentsplit.indexOf(sentHiddenWords[hiddenIdx])];
          var idxTemp = sentsplit.indexOf(sentHiddenWords[hiddenIdx]);
          listOfHiddenWords.push(hiddenWord);
          idxActHddnWordSent.push(idxTemp);
        }
      }
    });
    // End : Load content of From Sentence Map ..........

    var finResult = {
      idxHiddenWord: idxHiddenWord,
      listOfHiddenWords: listOfHiddenWords,
      idxActHddnWordSent: idxActHddnWordSent,
    };
    return finResult;
  }
  // Display content of body
  useEffect(() => {
    if (detailsOfSelLetter.level3[randomNumber].length !== 0) {
      // Start : Load content of Body ..........
      var letterBodyDetails = getDetailsOfHiddenWords(
        detailsOfSelLetter.level3[randomNumber].body
      );

      setIdxActHiddnWordSent([...letterBodyDetails.idxActHddnWordSent]);
      // End : Load content of Body ............

      var completedWordList = [...letterBodyDetails.listOfHiddenWords];

      //Shuffle list of words for random display ...
      // completedWordList.sort(() => 0.5 - Math.random());
      setFinalCompleteList([...completedWordList]);
    }

    //inserting first dropdown element as it is into an selectedAnsArray
    selectedAns.push(detailsOfSelLetter.level3[randomNumber].hiddenWords[0]);
    setAnswerArray([...detailsOfSelLetter.level3[randomNumber].hiddenWords]);
  }, [randomNumber]);

  const handleNext = () => {
    setShowMessage(false);
    setDisabledNext(true);
    finalCompleteList.forEach((word) => {
      if (word !== "") {
        var listOfElementbyName = document.getElementsByName(word);
        for (var i = 0; i < listOfElementbyName.length; i++) {
          document.getElementsByName(word)[i].style.backgroundColor = "";
          document.getElementsByName(word)[i].style.color = "";
        }
      }
    });

    document.querySelectorAll("select.selectdropdown").forEach((dropdown) => {
      dropdown.disabled = false; // ✅ Re-enable all dropdowns
      dropdown.style.backgroundColor = "#F5B946"; // Optional: reset color
      dropdown.style.color = "black"; // Optional: reset color
    });

    setSelectedAns([]);
    setFinalCompleteList([]);
    randomNumber = Math.floor(Math.random() * detailsOfSelLetter.level3.length);
    if (randomNumberArray.length !== 5) {
      if (randomNumberArray.includes(randomNumber)) {
        handleNext();
      } else {
        setRandomNumberArray((prevState) => [...prevState, randomNumber]);
        setRandomNumber(randomNumber);
      }
    } else {
      navigate(
        "/launchpage/englishactivity/selectlevel/level1/level2/level3/restart",
        {
          state: {
            attempted: 5 - skipCount,
            levelName: "Personal and possessive pronoun",
            totalCount: 5,
            type: "paraghaphs",
            levelToRestart: "Level 3",
          },
        }
      );
    }

    ReactGA.event({
      action: `Eng9|Personal and possessive pronoun|Clicked on "NEXT" button of level-3`,
      category: `Eng9|next button clicked`,
      label: `Eng9|Clicked on next button`,
    });

    SendLogData(
      sendJsonMessage,
      pageName,
      "NEXT",
      "Clicked",
      "Clicked to move to the next sentence",
      [{ input: "", answer: "", result: "" }],
      [
        {
          popuptype: "",
          popuptext: "",
        },
      ],
      [{ hint: "" }]
    );
  };

  const handleSkip = () => {
    let newSkipCount = skipCount + 1;
    setSkipCount(newSkipCount);
    handleNext();

    ReactGA.event({
      action: `Eng9|Personal and possessive pronoun|Clicked on "SKIP" button of level-3`,
      category: `Eng9|SKIP button clicked`,
      label: `Eng9|Clicked on SKIP button`,
    });

    SendLogData(
      sendJsonMessage,
      pageName,
      "SKIP",
      "Clicked",
      "Clicked to skip the sentence",
      [{ input: "", answer: "", result: "" }],
      [
        {
          popuptype: "",
          popuptext: "",
        },
      ],
      [{ hint: "" }]
    );
  };

  const handleChange = (event) => {
    setLevel(event.target.value);
    switch (event.target.value) {
      case "Level 1":
        navigate("/launchpage/englishactivity/level1");
        ReactGA.event({
          action: `Eng9|Personal and possessive pronoun|Clicked on dropdown to navigate to the level-1`,
          category: `Eng9|level Dropdown clicked`,
          label: `Eng9|Clicked on Level Dropdown`,
        });

        SendLogData(
          sendJsonMessage,
          pageName,
          "Dropdown",
          "Clicked",
          "Clicked to navigate to level-1",
          [{ input: "", answer: "", result: "" }],
          [
            {
              popuptype: "",
              popuptext: "",
            },
          ],
          [{ hint: "" }]
        );
        break;
      case "Level 2":
        navigate("/launchpage/englishactivity/level1/level2");
        ReactGA.event({
          action: `Eng9|Personal and possessive pronoun|Clicked on dropdown to navigate to the level-2`,
          category: `Eng9|level Dropdown clicked`,
          label: `Eng9|Clicked on Level Dropdown`,
        });

        SendLogData(
          sendJsonMessage,
          pageName,
          "Dropdown",
          "Clicked",
          "Clicked to navigate to level-2",
          [{ input: "", answer: "", result: "" }],
          [
            {
              popuptype: "",
              popuptext: "",
            },
          ],
          [{ hint: "" }]
        );
        break;
      case "Level 3":
        navigate("/launchpage/englishactivity/level1/level2/level3");
        ReactGA.event({
          action: `Eng9|Personal and possessive pronoun|Clicked on dropdown to navigate to the level-3`,
          category: `Eng9|level Dropdown clicked`,
          label: `Eng9|Clicked on Level Dropdown`,
        });

        SendLogData(
          sendJsonMessage,
          pageName,
          "Dropdown",
          "Clicked",
          "Clicked to navigate to level-3",
          [{ input: "", answer: "", result: "" }],
          [
            {
              popuptype: "",
              popuptext: "",
            },
          ],
          [{ hint: "" }]
        );
        break;

      default:
        console.log("Bad choice!");
        break;
    }
  };

  const handledropdownchange = (event, index) => {
    setShowMessage(false);
    const selectedValue = event.target.value;
    const correctAnswer = answerArray[index];
    selectedAns[index] = selectedValue;

    // Set background color based on correctness
    if (selectedValue === correctAnswer) {
      event.target.style.backgroundColor = "green";
      event.target.style.color = "white";
      event.target.disabled = true;
    } else {
      event.target.style.backgroundColor = "red";
      event.target.style.color = "white";
      event.target.disabled = false;
    }

    // Check if all answers are now correct
    const allCorrect = answerArray.every(
      (answer, i) => selectedAns[i] === answer
    );

    if (allCorrect) {
      setDisabledNext(false);
      setFlag(true);

      Swal.fire({
        icon: "success",
        // title: "Great job!",
        text: "All correct pronouns are selected.",
        customClass: {
          title: "green-text",
          htmlContainer: "green-text",
        },
      });
    } else {
      setDisabledNext(true);
    }

    setFbMessage(
      detailsOfSelLetter.level3[randomNumber].body[index].feedback[
        selectedValue
      ]
    );
    setShowMessage(true);
  };

  return (
    <div
      className="row d-flex scrollbar-primary"
      style={{
        width: "100vw",
        backgroundColor: "#F2FBFF",
        borderRadius: "14px",
        opacity: 1,
        boxShadow: "0px 10px 5px rgba(0, 0, 0, 0.40)",
        display: "block",
        overflow: "auto",
      }}
    >
      <div className="col-sm-9 d-flex justify-content-center align-items-center">
        <div
          className="scrollbar-primary"
          style={{
            height: "80vh",
            width: "95%",
            background: "#FFFFFF 0% 0% no-repeat padding-box",
            borderRadius: "13px",
            boxShadow: "0px 4px 7px #00000029",
            display: "block",
            padding: "4%",
            paddingTop: "0%",
            overflow: "auto",
            overflowX: "hidden",
            margin: "5px",
            fontSize: "calc(.6rem + .4vw)",
          }}
        >
          <div className="row align-items-center mb-5 mt-2">
            <div className="col-12 col-md-6 d-flex justify-content-end mb-2 mb-md-0">
              <div
                className="fw-bolder"
                style={{ fontSize: "calc(1rem + .4vw)" }}
              >
                Personal and possessive pronoun
              </div>
            </div>

            <div className="col-12 col-md-6 d-flex justify-content-md-end justify-content-center">
              <FormControl size="small" sx={{ minWidth: 120 }}>
                <Select
                  labelId="demo-simple-select-label"
                  id="demo-simple-select"
                  value={level} // Step 3: Set the value prop
                  onChange={handleChange}
                  sx={{
                    bgcolor: "green", // Set background color
                    borderRadius: "8px", // Set border radius
                    "& .MuiOutlinedInput-notchedOutline": {
                      borderColor: "green", // Set border color if needed
                    },
                    color: "white",
                    fontSize: "calc(.6rem + .4vw)",
                  }}
                >
                  <MenuItem value="Level 1">{t("level1")}</MenuItem>
                  <MenuItem value="Level 2">{t("level2")}</MenuItem>
                  <MenuItem value="Level 3">{t("level3")}</MenuItem>
                </Select>
              </FormControl>
            </div>
          </div>

          <div className="row mb-3">
            <div className="d-flex align-items-center">
              <span className="me-3">Paragraph</span>

              <Slider
                defaultValue={1}
                step={1}
                min={1}
                max={5}
                value={randomNumberArray.length}
                color="success"
                marks
                valueLabelDisplay="on"
                sx={{
                  "& .MuiSlider-mark": {
                    width: 12,
                    height: 12,
                    borderRadius: "50%",
                  },
                }}
              />
              <span
                className="ms-3"
                style={{
                  height: "40px",
                  width: "45px",
                  borderRadius: "50%",
                  backgroundColor: "lightblue",
                  display: "flex",
                  justifyContent: "center",
                  alignItems: "center",
                }}
              >
                {randomNumberArray.length}/{5}
              </span>
            </div>
          </div>
          <div className="" style={{ height: "auto" }}>
            <div
              className="row-md-auto"
              style={{
                height: "auto",
                borderRadius: "20px",
                background: "#EDF6FA",
                paddingTop: "2%",
                paddingBottom: "2%",
              }}
            >
              <div
                className="row"
                style={{
                  borderRadius: "8px",
                  marginLeft: "0.1%",
                  marginRight: "0.1%",
                  paddingLeft: "1%",
                  paddingTop: "1%",
                }}
              >
                <div className="row-md-auto" style={{ height: "90%" }}>
                  {/* ################ Body : Start : Display the contents of the Body ################### */}
                  <div className="row-md-auto wrap">
                    <div
                      style={{
                        maxWidth: "100%",
                        display: "inline-flex",
                        flexWrap: "wrap",
                        textAlign: "left",
                        margin: "0 auto",
                        lineHeight: "30px",
                      }}
                    >
                      {detailsOfSelLetter.level3[randomNumber].body.map(
                        (slotitem, index1) =>
                          slotitem.sentence.split(" ").map((word, index) => (
                            <>
                              {finalIdxActHiddnWordSent[index1] === index ? (
                                <select
                                  className="selectdropdown"
                                  name={word}
                                  onChange={(e) =>
                                    handledropdownchange(
                                      e,
                                      slotitem.sent_id - 1,
                                      slotitem.hidden
                                    )
                                  }
                                >
                                  {Object.keys(slotitem.options).map(
                                    (optionKey, idx) => (
                                      <>
                                        {optionKey === word ? (
                                          <>
                                            {slotitem.options[optionKey].map(
                                              (optionWord, optionidx) => (
                                                <option
                                                  key={optionidx}
                                                  value={optionWord}
                                                >
                                                  {optionWord}
                                                </option>
                                              )
                                            )}
                                          </>
                                        ) : (
                                          <></>
                                        )}
                                      </>
                                    )
                                  )}
                                </select>
                              ) : (
                                <div
                                  key={
                                    "body_" + word + "_" + index1 + "_" + index
                                  }
                                  style={{
                                    minWidth: "20px",
                                    paddingRight: "5px",
                                    marginBottom: "0.5%",
                                    marginTop: "0.5%",
                                  }}
                                >
                                  {word}
                                </div>
                              )}
                            </>
                          ))
                      )}
                    </div>
                  </div>
                  {/* ################ Body : End : Display the contents of the Body ################### */}
                </div>
              </div>
            </div>
            <div className="d-flex justify-content-around mt-3 mb-5">
              <Button
                variant="contained"
                onClick={handleSkip}
                sx={{
                  background: "#0F477E",
                  color: "#ffffff",
                  fontSize: "calc(.6rem + .4vw)",
                }}
              >
                {t("skip")}
              </Button>

              <Button
                variant="contained"
                onClick={handleNext}
                disabled={disabledNext}
                sx={{
                  background: "#0F477E",
                  color: "#ffffff",
                  fontSize: "calc(.6rem + .4vw)",
                }}
              >
                {randomNumberArray.length == 5 ? t("finish") : t("next")}
              </Button>
            </div>
            <div className="row justify-content-center">
              {showMessage && (
                <div
                  className="d-flex justify-content-center align-items-center"
                  style={{
                    width: "auto",
                    height: "auto",
                    background: "#ffffff",
                    boxShadow: "0px 0px 5px rgba(0, 0, 0, 0.5)",
                    borderRadius: "50px",
                    padding: "2%",
                  }}
                >
                  <div>{parse(fbMessage)}</div>
                </div>
              )}
            </div>
          </div>
        </div>
      </div>

      <div className="col-sm-3 d-flex justify-content-center align-items-center">
        <div
          className="scrollbar-primary"
          style={{
            height: "80vh",
            width: "95%",
            overflow: "auto",
            overflowX: "hidden",
            borderRadius: "13px",
            boxShadow: "0px 4px 7px #00000029",
            display: "block",
            background: "#FFFFFF 0% 0% no-repeat padding-box",
            margin: "5px",
          }}
        >
          <div
            className="sticky-top text-center"
            style={{
              background: "#002F65",
              borderRadius: "10px 10px 0px 0px",
              opacity: "1",
              color: "#FFFFFF",
              fontSize: "calc(1rem + 0.2vw)",
              fontWeight: "bolder",
            }}
          >
            {t("instr")}
          </div>
          <div
            style={{
              maxHeight: "50vh",
              padding: "2%",
              lineHeight: "30px",
              fontSize: "calc(.6rem + .4vw)",
            }}
          >
            <ul>
              {randomNumberArray.length === 1 && (
                <>
                  <li>{t("instr11")}</li>
                  <li>{t("instr12")}</li>
                  <li>{t("instr13")}</li>
                  <li>{t("instr15")}</li>
                </>
              )}

              {randomNumberArray.length !== 1 && disabledNext && (
                <>
                  <li>{t("instr12")}</li>
                  <li>{t("instr13")}</li>
                  <li>{t("instr15")}</li>
                </>
              )}

              {disabledNext ? (
                <li>{t("instr17")}</li>
              ) : randomNumberArray.length === 5 ? (
                <li>{t("instr16")}</li>
              ) : (
                <li>{t("instr14")}</li>
              )}
            </ul>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Level3MidContent;
